function ticketTiers(text) {
  if (!text) return [];
  const result = [];
  const lines = text.split("\n").map((line) => line.trim()).filter(Boolean);
  let pendingName = "";
  for (const line of lines) {
    if (line.startsWith("※") || line.startsWith("▼")) continue;
    if (/チケット代無料/.test(line)) {
      result.push({ name: "チケット代", displayAmount: 0, amountMinorUnits: 0, currency: "JPY" });
      continue;
    }
    const prefixMatch = line.match(/^(.*?)(?:[:：]\s*)?(NT\$|HK\$|[¥￥])\s*([\d,]+)/);
    const yenMatch = line.match(/^(.*?)([\d,]+)円/);
    if (!prefixMatch && !yenMatch) {
      if (!/^(グッズ|会場|当日券|販売|特典|エリア|オールスタンディング)/.test(line)) pendingName = line;
      continue;
    }
    const namePart = prefixMatch?.[1] ?? yenMatch?.[1] ?? "";
    const amountPart = prefixMatch?.[3] ?? yenMatch?.[2] ?? "";
    let name = namePart.replace(/[\s:：]+$/, "").trim();
    if (!name) name = pendingName;
    name = name.replace(/\s+(受付終了|※.*)$/, "").trim();
    if (!name || /^(DAY|日程|引換|発売時間)/.test(name)) continue;
    const prefix = prefixMatch?.[2] ?? "";
    const currency = prefix === "NT$" ? "TWD" : prefix === "HK$" ? "HKD" : "JPY";
    const displayAmount = Number(amountPart.replaceAll(",", ""));
    result.push({
      name,
      displayAmount,
      amountMinorUnits: currency === "JPY" ? displayAmount : displayAmount * 100,
      currency,
    });
  }
  return result.filter((tier, index, all) =>
    all.findIndex((candidate) => JSON.stringify(candidate) === JSON.stringify(tier)) === index,
  );
}

const titleNotes = {
  25272: "REST title omits DAY2; current HTML h1 is authoritative and says DAY2.",
  13991: "Distinct DAY1 publication URL currently serves the merged two-day Taipei page; duplicate content group taipei-2026.",
  13993: "Distinct DAY2 publication URL currently serves the merged two-day Taipei page; duplicate content group taipei-2026.",
  13967: "REST title is tour-wide; current linked HTML is the Hong Kong landing page.",
  13876: "REST title is tour-wide; current linked HTML is the Fukuoka landing page.",
};

const expected = facts.map((fact) => {
  const id = fact.wordpressID;
  const items = (performances[id] ?? []).map((item) => ({ timeZone: "Asia/Tokyo", ...item }));
  return {
    publicationRank: fact.publicationRank,
    wordpressID: id,
    url: fact.url,
    officialTitle: fact.title.value,
    expectedPerformanceCount: items.length,
    performances: items,
    ticketTiers: ticketTiers(fact.prices?.text),
    ticketRoundNames: fact.ticketRounds.map((round) => round.name),
    eventGoodsImages: fact.eventGoodsImages.map((image) => ({
      section: image.section,
      caption: image.caption,
      url: image.linkedOriginalURL ?? image.url,
    })),
    notes: titleNotes[id] ? [titleNotes[id]] : [],
  };
});

const missing = expected.filter((item) => item.expectedPerformanceCount === 0);
if (missing.length) throw new Error(`Missing hand review for: ${missing.map((item) => item.wordpressID).join(", ")}`);

fs.writeFileSync(path.join(here, "normalized-expected.json"), `${JSON.stringify(expected, null, 2)}\n`);
console.log(`Wrote ${expected.length} hand-reviewed normalized records.`);
